    conversationJourneys = pgTable("conversation_journeys", {
      id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
      businessAccountId: varchar("business_account_id").notNull().references(() => businessAccounts.id, { onDelete: "cascade" }),
      // Journey details
      name: text("name").notNull(),
      // e.g., "Educational Counsellor", "Lead Qualification"
      description: text("description"),
      // Optional description of what this journey does
      templateType: text("template_type").notNull().default("custom"),
      // 'educational_counsellor' | 'lead_qualification' | 'appointment_booking' | 'product_discovery' | 'custom'
      // Journey type
      journeyType: text("journey_type").notNull().default("conversational"),
      // 'conversational' (AI-guided chat) | 'form' (step-by-step UI components)
      // Status and behavior
      status: text("status").notNull().default("active"),
      // 'active' | 'inactive'
      isDefault: text("is_default").notNull().default("false"),
      // 'true' | 'false' - Whether this journey auto-starts for new conversations
      triggerMode: text("trigger_mode").notNull().default("manual"),
      // 'manual' | 'auto' | 'conditional'
      triggerKeywords: text("trigger_keywords"),
      // JSON array of keywords that trigger this journey (e.g., ["book appointment", "schedule meeting"])
      startFromScratch: text("start_from_scratch").notNull().default("false"),
      // 'true' | 'false' - If true, journey starts immediately (first step is the greeting), no keywords needed
      // Journey-specific AI training
      conversationalGuidelines: text("conversational_guidelines"),
      // Optional instructions for AI tone, acknowledgments, and conversational style specific to this journey
      // Usage tracking
      totalStarts: numeric("total_starts", { precision: 10, scale: 0 }).notNull().default("0"),
      totalCompletions: numeric("total_completions", { precision: 10, scale: 0 }).notNull().default("0"),
      createdAt: timestamp("created_at").notNull().defaultNow(),
      updatedAt: timestamp("updated_at").notNull().defaultNow()
    });
    journeySteps = pgTable("journey_steps", {
      id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
      journeyId: varchar("journey_id").notNull().references(() => conversationJourneys.id, { onDelete: "cascade" }),
      // Step details
      stepOrder: numeric("step_order", { precision: 5, scale: 0 }).notNull(),
      // Order in sequence (0, 1, 2, ...)
      questionText: text("question_text").notNull(),
      // The question to ask user
      questionType: text("question_type").notNull().default("text"),
      // 'text' | 'multiple_choice' | 'yes_no' | 'number' | 'email' | 'phone'
      // Field configuration
      fieldName: text("field_name"),
      // Optional - field name for storing response (e.g., "budget", "interest_area")
      crmFieldKey: text("crm_field_key"),
      // Optional - CRM field key this step's answer maps to (referenced as journey.<key> in LeadSquared field mappings)
      isRequired: text("is_required").notNull().default("false"),
      // 'true' | 'false' - Whether user must answer before continuing
      multipleChoiceOptions: text("multiple_choice_options"),
      // JSON array of options for multiple_choice type
      // Tool integration
      toolTrigger: text("tool_trigger"),
      // Optional tool to trigger after this step: 'capture_lead' | 'book_appointment' | 'get_products' | null
      toolParameters: text("tool_parameters"),
      // JSON object of tool parameters to pass
      // Branching logic (conditional routing)
      branchingCondition: text("branching_condition"),
      // JSON object: { "routes": [{ "matchType": "contains", "matchValue": "MBA", "targetStepId": "uuid", "label": "If MBA" }], "defaultNextStepId": null }
      // Exit on answer - stops journey when specific answer is selected
      exitOnValue: text("exit_on_value"),
      // The answer value that triggers journey exit (e.g., "No")
      exitMessage: text("exit_message"),
      // Message to show when journey exits early
      // Skip to step - jump to specific step when specific answer is selected
      skipOnValue: text("skip_on_value"),
      // The answer value that triggers step skip (e.g., "No")
      skipToStepIndex: integer("skip_to_step_index"),
      // The step order to skip to (e.g., 5)
      // Conditional step - only shown when explicitly skipped to, not during normal progression
      isConditional: text("is_conditional").notNull().default("false"),
      // 'true' | 'false'
      // Journey Complete step configuration
      completionButtonText: text("completion_button_text"),
      // Button text for "Continue Exploring" or similar
      // Help text and placeholders
      placeholderText: text("placeholder_text"),
      // Placeholder for input field
      helpText: text("help_text"),
      // Additional guidance for user
      createdAt: timestamp("created_at").notNull().defaultNow(),
      updatedAt: timestamp("updated_at").notNull().defaultNow()
    });
