      tokensInput: numeric("tokens_input", { precision: 15, scale: 0 }).notNull().default("0"),
      // Total input tokens for this day
      tokensOutput: numeric("tokens_output", { precision: 15, scale: 0 }).notNull().default("0"),
      // Total output tokens for this day
