    whatsappSettings = pgTable("whatsapp_settings", {
      id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
      businessAccountId: varchar("business_account_id").notNull().unique().references(() => businessAccounts.id, { onDelete: "cascade" }),
      whatsappEnabled: text("whatsapp_enabled").notNull().default("true"),
      // 'true' | 'false' - master toggle for WhatsApp AI Agent
      msg91AuthKey: text("msg91_auth_key"),
      // Encrypted MSG91 auth key
      whatsappNumber: text("whatsapp_number"),
      // WhatsApp Business phone number
      webhookSecret: text("webhook_secret"),
      // Secret for webhook validation
      extractionFields: jsonb("extraction_fields").$type().default(["name", "phone", "email"]),
      // Fields to extract
      customPrompt: text("custom_prompt"),
      // Optional custom AI extraction prompt
      autoSyncToLeadsquared: text("auto_sync_to_leadsquared").notNull().default("false"),
      // 'true' | 'false'
      // Lead capture settings
      leadCaptureEnabled: text("lead_capture_enabled").notNull().default("true"),
      // 'true' | 'false' - enable/disable auto lead capture
      leadGenerationMode: text("lead_generation_mode").notNull().default("first_message"),
      // 'first_message' | 'flow_only'
      requireName: text("require_name").notNull().default("false"),
      // 'true' | 'false' - require name to create lead
      requirePhone: text("require_phone").notNull().default("false"),
      // 'true' | 'false' - require phone to create lead
      requireEmail: text("require_email").notNull().default("false"),
      // 'true' | 'false' - require email to create lead
      minFieldsRequired: integer("min_fields_required").notNull().default(1),
      // Minimum number of fields that must be extracted
      // Auto-reply settings
      autoReplyEnabled: text("auto_reply_enabled").notNull().default("false"),
      // 'true' | 'false' - enable AI auto-reply
      msg91IntegratedNumberId: text("msg91_integrated_number_id"),
      // MSG91 integrated number ID for sending messages
      newApplicationCooldownDays: integer("new_application_cooldown_days").notNull().default(7),
      phoneNumberLength: integer("phone_number_length").notNull().default(10),
      updateLeadEnabled: text("update_lead_enabled").notNull().default("true"),
      // 'true' | 'false' - show Add Documents / Update Details options for duplicate phone
      useMasterTraining: text("use_master_training").notNull().default("true"),
      // 'true' | 'false' - apply custom AI instructions in WhatsApp flow
      useLeadTraining: text("use_lead_training").notNull().default("true"),
      // 'true' | 'false' - apply lead training config in WhatsApp flow
      whitelistEnabled: text("whitelist_enabled").notNull().default("false"),
      // 'true' | 'false' - only process messages from whitelisted numbers
      sessionTemplateName: text("session_template_name"),
      // Approved WhatsApp template name for re-engagement after 24h window expires
      sessionTemplateNamespace: text("session_template_namespace"),
      // Template namespace (if required by MSG91)
      docConfirmationEnabled: text("doc_confirmation_enabled").notNull().default("false"),
      // 'true' | 'false' - show extracted fields for user confirmation before proceeding
      docConfirmationMode: text("doc_confirmation_mode").notNull().default("per_document"),
      // 'per_document' | 'after_all_documents'
      docConfirmationHeader: text("doc_confirmation_header").default("Please review the details extracted from your document:"),
      docConfirmationFooter: text("doc_confirmation_footer").default("Are these details correct?"),
      // Use Case Mode (Phase 1) — root context signal for persona builder + flow exit-intent classifier.
      // Values: 'lead_capture' (internal staff submitting leads on behalf of customers — default for existing accounts),
      //         'direct_sales' (AI sells directly to prospects), 'customer_support' (AI helps existing customers).
      useCaseMode: text("use_case_mode").notNull().default("lead_capture"),
      // AI Setup (declutter) — response mode chooses how inbound messages are handled.
      // Values: 'smart_ai' (AI handles everything, flows bypassed), 'guided_flows' (scripted flows only,
      //         AI replies only on explicit flow handoff), 'both' (flows first, AI handles the rest).
      // null = legacy behavior (flow-first with AI fallback on unhandled) — preserved for existing accounts.
      aiResponseMode: text("ai_response_mode"),
      // Per-source knowledge toggles — control which training data is fed to the AI before it replies on WhatsApp.
      useFaqKnowledge: text("use_faq_knowledge").notNull().default("true"),
      // 'true' | 'false'
      useDocumentKnowledge: text("use_document_knowledge").notNull().default("true"),
      // 'true' | 'false'
      useWebsiteKnowledge: text("use_website_knowledge").notNull().default("true"),
      // 'true' | 'false'
      useProductCatalogKnowledge: text("use_product_catalog_knowledge").notNull().default("true"),
      // 'true' | 'false'
      createdAt: timestamp("created_at").notNull().defaultNow(),
      updatedAt: timestamp("updated_at").notNull().defaultNow()
    });
    insertWhatsappSettingsSchema = createInsertSchema(whatsappSettings).omit({
      id: true,
      createdAt: true,
      updatedAt: true
    });
