    whatsappLeads = pgTable("whatsapp_leads", {
      id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
      businessAccountId: varchar("business_account_id").notNull().references(() => businessAccounts.id, { onDelete: "cascade" }),
      whatsappMessageId: text("whatsapp_message_id"),
      // MSG91 message ID
      senderPhone: text("sender_phone"),
      // Salesman's phone number
      senderName: text("sender_name"),
      // Salesman name (if known)
      customerName: text("customer_name"),
      // Extracted customer name
      customerPhone: text("customer_phone"),
      // Extracted customer phone
      customerEmail: text("customer_email"),
      // Extracted customer email
      notes: text("notes"),
      // Any additional notes
      rawMessage: text("raw_message"),
      // Original WhatsApp message text
      extractedData: jsonb("extracted_data"),
      // Full AI extraction result as JSON
      status: text("status").notNull().default("new"),
      // 'new' | 'processing' | 'completed' | 'rejected' | 'message_only'
      direction: text("direction").notNull().default("incoming"),
      // 'incoming' | 'outgoing' - message direction
      flowSessionId: varchar("flow_session_id"),
      // Links message to a WhatsApp flow session for journey grouping
      leadsquaredLeadId: text("leadsquared_lead_id"),
      // LeadSquared lead ID if synced
      leadsquaredSyncStatus: text("leadsquared_sync_status"),
      // null | 'pending' | 'synced' | 'failed'
      leadsquaredSyncError: text("leadsquared_sync_error"),
      // Error message if sync failed
      customCrmSyncStatus: text("custom_crm_sync_status"),
      // null | 'pending' | 'synced' | 'failed'
      customCrmLeadId: text("custom_crm_lead_id"),
      customCrmSyncError: text("custom_crm_sync_error"),
      customCrmSyncPayload: jsonb("custom_crm_sync_payload"),
      customCrmSyncedAt: timestamp("custom_crm_synced_at"),
      // Verification engine (Task #5 — configurable verification engine POC)
      verificationResults: jsonb("verification_results"),
      // Last verification run result (see VerificationResult shape)
      verificationRunAt: timestamp("verification_run_at"),
      // When verification was last run on this lead
      lastMessageAt: timestamp("last_message_at"),
      // When the most recent message was received (for sorting by activity)
      lastMessage: text("last_message"),
      // Text of the most recent message
      conversationCount: integer("conversation_count").notNull().default(1),
      // Number of messages/interactions on this lead
      receivedAt: timestamp("received_at").notNull().defaultNow(),
      // When message was received
      createdAt: timestamp("created_at").notNull().defaultNow(),
      updatedAt: timestamp("updated_at").notNull().defaultNow()
    }, (table) => ({
      businessReceivedIdx: index("whatsapp_leads_business_received_idx").on(table.businessAccountId, table.receivedAt),
      businessLastMessageIdx: index("whatsapp_leads_business_last_message_idx").on(table.businessAccountId, table.lastMessageAt),
      blankPlaceholderUniqueIdx: uniqueIndex("whatsapp_leads_blank_placeholder_unique_idx").on(table.businessAccountId, table.senderPhone).where(sql`status = 'new' AND customer_name IS NULL AND extracted_data IS NULL`)
    }));
