            console.log(`[VisionWarehouseSync] Found in-progress ${phase} operation: ${existingOp}, type: ${discoveredOpType}`);
            const updateFields = phase === "analyzing" ? { visionWarehouseSyncAnalyzeOpName: existingOp } : { visionWarehouseSyncIndexOpName: existingOp, visionWarehouseSyncIndexOpType: discoveredOpType };
