async function ensureSeedRuleSet(businessAccountId) {
  const existingRows = await db.select().from(verificationRuleSets).where(and31(
    eq40(verificationRuleSets.businessAccountId, businessAccountId),
    eq40(verificationRuleSets.isSystemSeed, true)
  ));
  let existing = existingRows.find((r) => r.name === SEED_NAME) ?? existingRows.find((r) => LEGACY_SEED_NAMES.includes(r.name));
  if (!existing) {
    const [legacyByName] = await db.select().from(verificationRuleSets).where(and31(
      eq40(verificationRuleSets.businessAccountId, businessAccountId),
      eq40(verificationRuleSets.name, SEED_NAME)
    )).limit(1);
    existing = legacyByName;
  }
  if (existing) {
    if (existing.name !== SEED_NAME) {
      await db.update(verificationRuleSets).set({ name: SEED_NAME, description: SEED_DESCRIPTION }).where(eq40(verificationRuleSets.id, existing.id));
    }
    return existing.id;
  }
  const [created] = await db.insert(verificationRuleSets).values({
    businessAccountId,
    name: SEED_NAME,
    description: SEED_DESCRIPTION,
    isActive: true,
    isSystemSeed: true
  }).returning();
  await db.insert(verificationRules).values(
    SEED_RULES.map((r) => ({
      ruleSetId: created.id,
      ruleType: r.ruleType,
      name: r.name,
      severity: r.severity,
      sortOrder: r.sortOrder,
      config: r.config,
      messageTemplate: r.messageTemplate,
      isActive: true
    }))
  );
  console.log(`[Verification] Seeded "${SEED_NAME}" for business ${businessAccountId}`);
  return created.id;
}

