  app2.get("/api/database/backup", requireAuth, requireRole("super_admin"), async (req, res) => {
    try {
      const timestamp2 = Date.now();
      const filename = `database_backup_${timestamp2}.sql`;
      const backupPath = path5.join(__dirname, "..", "tmp", filename);
      const tmpDir = path5.join(__dirname, "..", "tmp");
      if (!fs3.existsSync(tmpDir)) {
        fs3.mkdirSync(tmpDir, { recursive: true });
      }
      const databaseUrl = process.env.DATABASE_URL;
      if (!databaseUrl) {
        return res.status(500).json({ error: "Database URL not configured" });
      }
      await execAsync(`pg_dump "${databaseUrl}" > "${backupPath}"`);
      if (!fs3.existsSync(backupPath)) {
        return res.status(500).json({ error: "Failed to create backup file" });
      }
      res.setHeader("Content-Type", "application/sql");
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      const fileStream = fs3.createReadStream(backupPath);
      fileStream.pipe(res);
      fileStream.on("end", () => {
        fs3.unlink(backupPath, (err) => {
          if (err) console.error("Failed to delete backup file:", err);
        });
      });
    } catch (error) {
      console.error("[Database Backup] Error:", error);
      res.status(500).json({ error: "Failed to create database backup" });
    }
  });
